public with sharing class Opportunities extends fflib_SObjectDomain {
    private final List<Opportunity> listOpportunities = new List<Opportunity>();

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain getNewSObjectDomain(fflib_SObjectDomainEvent event) {
            return new Opportunities(event);
        }
    }

    public Opportunities(fflib_SObjectDomainEvent event) {
        if (event != null && event.getSObjects() != null) {
            for (SObject sObject : event.getSObjects()) {
                listOpportunities.add((Opportunity) sObject);
            }
        }
    }

    public virtual fflib_SObjectDomain getNewSObjectDomain(fflib_SObjectDomainEvent event) {
        return new Constructor().getNewSObjectDomain(event);
    }

    public virtual void run(fflib_SObjectDomainEvent event) {
        if (event != null && event.isEvent(fflib_SObjectDomainEvent.BEFORE_INSERT)) {
            Date defaultCloseDate = Date.today().addDays(30);

            for (Opportunity opp : listOpportunities) {
                if (opp.CloseDate == null) {
                    opp.CloseDate = defaultCloseDate;
                }

                if (String.isBlank(opp.Type)) {
                    opp.Type = 'New Customer';
                }
            }
        }
    }
}
