    private Integer m_offset;
    private Integer m_limit;
    private String m_sosl;
    public fflib_SObjectSelector(Type sObjectType, List<String> fieldList) {
        m_sObjectType = sObjectType;
        m_fieldList = fieldList;
    }
    public virtual void addField(String field) {
        if (m_fieldList == null) m_fieldList = new List<String>();
        m_fieldList.add(field);
    }
    public virtual void addFieldList(List<String> fieldList) {
        if (m_fieldList == null) m_fieldList = new List<String>();
        m_fieldList.addAll(fieldList);
    }
    public virtual void setOrdering(String orderByClause) { m_orderByClause = orderByClause; }
    public virtual void setSecurityEnforced(Boolean securityEnforced) { m_securityEnforced = securityEnforced; }
    public virtual void setOffset(Integer offset) { m_offset = offset; }
    public virtual void setLimit(Integer limit) { m_limit = limit; }
    public virtual void setSosl(String sosl) { m_sosl = sosl; }
    public virtual String buildQuery() {
        if (m_sosl != null) return m_sosl;
        if (m_sObjectType == null) throw new fflib_ApexException('SObject type is null');
        if (m_fieldList == null || m_fieldList.size() == 0) throw ...
        String soql = 'SELECT ' + String.join(m_fieldList, ', ') + ' FROM ' + m_sObjectType.getName();
        if (m_orderByClause != null) soql += ' ORDER BY ' + m_orderByClause;
        if (m_offset != null && m_limit != null) soql += ' LIMIT ' + m_limit + ' OFFSET ' + m_offset;
        else if (m_limit != null) soql += ' LIMIT ' + m_limit;
        return soql;
    }
    public virtual List<SObject> selectQueryResult() {
        if (m_securityEnforced) {
            return Database.query(buildQuery());
        } else {
            return Database.query(buildQuery(), AccessLevelWithoutSecurityEnforcement);
