    private List<Schema.SObjectField> getAccountFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
        Set<String> existingFieldNames = new Set<String>{
            'Id',
            'Name',
            'Industry'
        };

        Schema.FieldSet fieldSet = Account.SObjectType.getDescribe().getFieldSet('Credit_Review');
